-- 00000000000008 — be seed data: public.config_entries (consolidated).
-- Sequence realignment for all manually-inserted id columns.



-- ─── Seed audit trail (seed-audit-trail standard) ───────────────────────

SELECT t.id, t.uuid, 'INSERT', t.created_at, 'initial-setup', t.version,
  jsonb_strip_nulls((SELECT jsonb_object_agg(kv.key, jsonb_build_object('old', null, 'new', kv.value)) FROM jsonb_each(to_jsonb(t)) kv))
FROM public.config_entries t
WHERE NOT EXISTS (SELECT 1 FROM public.config_entries_audit a WHERE a.entity_uuid = t.uuid);

SELECT pg_catalog.setval('public.translations_id_seq', (SELECT max(id) FROM public.translations));
SELECT pg_catalog.setval('system.translations_id_seq', (SELECT max(id) FROM system.translations));
SELECT pg_catalog.setval('public.config_entries_id_seq', (SELECT max(id) FROM public.config_entries));
